(* [comment removed for export] *)
Definition VC : list nat := [2; 5; 6; 7; 8; 9; 12; 13; 14; 15; 16; 17; 18; 19; 20; 28; 29; 30; 31]%nat.
Definition KL : list nat := [1; 3; 4; 27]%nat.

Definition vconst (R : bvmap 5 word) (S e : Z) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (S - 96) /\ getr R (reg 5) = Z_to_bv 64 239 /\ getr R (reg 6) = Z_to_bv 64 224 /\ getr R (reg 7) = Z_to_bv 64 160
  /\ getr R (reg 8) = Z_to_bv 64 244 /\ getr R (reg 9) = Z_to_bv 64 143 /\ getr R (reg 12) = Z_to_bv 64 e /\ getr R (reg 13) = Z_to_bv 64 8
  /\ getr R (reg 14) = Z_to_bv 64 1 /\ getr R (reg 15) = Z_to_bv 64 (-62) /\ getr R (reg 16) = Z_to_bv 64 245 /\ getr R (reg 17) = Z_to_bv 64 (-65)
  /\ getr R (reg 18) = Z_to_bv 64 2 /\ getr R (reg 19) = Z_to_bv 64 80513 /\ getr R (reg 20) = Z_to_bv 64 3 /\ getr R (reg 28) = Z_to_bv 64 237
  /\ getr R (reg 29) = Z_to_bv 64 159 /\ getr R (reg 30) = Z_to_bv 64 240 /\ getr R (reg 31) = Z_to_bv 64 144.
